        ///     const offset = input.len - rest.len;
        ///     if (stop.start != null) content_start = offset + stop.consumed;
        ///     if (stop.end != null) {
        ///         // The ending byte is consumed but is not content.
        ///         const content_end = offset + stop.consumed - 1;
